const response = $input.first().json;
const deepseekContent = response.choices[0].message.content;
const perplexityData = $('Extraer Respuesta Perplexity').first().json;

return [{
  json: {
    deepseek_brief: deepseekContent,
    perplexity_trends: perplexityData.perplexity_trends,
    fecha: perplexityData.fecha
  }
}];

const data = $input.first().json;
const fecha = data.fecha;
const trends = (data.perplexity_trends || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const brief = (data.deepseek_brief || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const trendsHtml = trends.split('\n').map(line => `<p>${line}</p>`).join('');
const briefHtml = brief.split('\n').map(line => `<p>${line}</p>`).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <style>
    * { box-sizing: border-box; }
    body { font-family: 'Arial', sans-serif; margin: 0; padding: 40px; color: #333; background: #fff; }
    .header { background: linear-gradient(135deg, #e91e8c, #9c27b0); color: white; padding: 30px; border-radius: 12px; margin-bottom: 30px; }
    .header h1 { margin: 0; font-size: 28px; }
    .header p { margin: 8px 0 0 0; opacity: 0.9; font-size: 14px; }
    .section { margin: 25px 0; padding: 25px; background: #f8f9fa; border-radius: 12px; border-left: 4px solid #e91e8c; }
    .section h2 { color: #9c27b0; margin-top: 0; font-size: 20px; }
    .section p { line-height: 1.7; margin: 6px 0; }
    .badge { display: inline-block; background: #e91e8c; color: white; padding: 4px 12px; border-radius: 20px; font-size: 12px; margin-bottom: 10px; }
    .footer { text-align: center; margin-top: 40px; color: #aaa; font-size: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>📊 Reporte de Tendencias IA</h1>
    <p>Generado automaticamente el ${fecha} • AI Instagram Model</p>
  </div>

  <div class="section">
    <span class="badge">🔍 PERPLEXITY</span>
    <h2>Investigacion de Tendencias del Dia</h2>
    ${trendsHtml}
  </div>

  <div class="section">
    <span class="badge">🤖 DEEPSEEK</span>
    <h2>Brief Creativo y Directrices de Contenido</h2>
    ${briefHtml}
  </div>

  <div class="footer">
    <p>Flujo automatizado n8n • AI Instagram Model • ${fecha}</p>
  </div>
</body>
</html>`;

return [{ json: { html_content: html, fecha } }];

const pdfData = $input.first().binary;
